import {t} from './i18n.mjs';
export function safeCitationUrl(value){try{const u=new URL(value);return u.protocol==='https:'&&!u.username&&!u.password&&!u.port&&!/^(localhost|127\.|0\.|\[|::)/.test(u.hostname)?u.href:null}catch{return null}}
export function citationLinks(ids,sources){const span=document.createElement('span');span.className='citation-links';for(const id of ids||[]){const source=sources?.find(s=>s.id===id),url=source&&safeCitationUrl(source.url);if(!url)continue;const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener noreferrer';a.textContent=source.title;span.append(a)}return span}
export function renderSources(node,sources=[],outputLicense){node.replaceChildren();if(!sources.length)return;for(const source of sources){const item=document.createElement('section');item.className='source-item';const link=citationLinks([source.id],sources),info=document.createElement('p');info.textContent=[source.provider,source.language,source.scope==='area'?t('Региональный контекст'):t('Об этом месте'),source.publishedAt?t('Опубликовано: ')+source.publishedAt:'',source.updatedAt?t('Обновлено: ')+source.updatedAt:'',source.retrievedAt?t('Проверено: ')+source.retrievedAt:''].filter(Boolean).join(' · ');const rights=document.createElement('p');rights.textContent=[source.license?.attribution,source.license?.id].filter(Boolean).join(' · ');const url=safeCitationUrl(source.license?.url);if(url){const a=document.createElement('a');a.href=url;a.textContent=t('Лицензия');a.target='_blank';a.rel='noopener noreferrer';rights.append(' · ',a)}item.append(link,info,rights);node.append(item)}if(outputLicense){const notice=document.createElement('p');notice.textContent=t('Текст и аудио — переработка источников: ')+outputLicense;node.append(notice)}}

